extern crate serde_json;

use serde_json::{self, Value};

pub fn get_json(executing_task: String) -> Result<String, Box<dyn std::error::Error>> {
    println!("Executing task: {}", executing_task);
    let task_data = executing_task.as_bytes();
    let json_data = serde_json::from_slice::<Value>(task_data)?;
    if get_task_info(json_data.to_string()) == Ok("response") {
        println!("Found response task");
        get_executor_task_data(json_data)
    } else {
        let response = String::from("Error");
        Ok(response)
    }
}

